class Artifact:
    def __init__(self, name, tags=None):
        self.name = name
        self.tags = list(tags) if tags is not None else []
        self.children = []
        self.featured = None


def clone_exhibit(root):
    if root is None:
        return None

    memo = {}

    def clone(node):
        if not isinstance(node, Artifact):
            raise TypeError("reachable values must be Artifact instances")
        if not isinstance(node.name, str):
            raise TypeError("artifact names must be strings")
        if not isinstance(node.tags, list) or any(not isinstance(tag, str) for tag in node.tags):
            raise TypeError("tags must be a list of strings")
        if not isinstance(node.children, list):
            raise TypeError("children must be a list")
        if node in memo:
            return memo[node]

        copied = Artifact(node.name, node.tags)
        copied.children = [clone(child) for child in node.children]
        copied.featured = None if node.featured is None else clone(node.featured)
        memo[node] = copied
        return copied

    return clone(root)

